type ListNode = { val: number; next: ListNode | null };
function chainInspectionBossReceipt(head: ListNode | null): number {
  const a=head; let out:number[]=[];
  for(let node=a;node;node=node.next)out.push(node.val);
  return out.reduce((s,x,i)=>s+(i+1)*x,0);
}


python
def chainInspectionBossReceipt(head):
    a=head
    out=[]
    node=a
    while node:
        out.append(node.val)
        node=node.next
    return sum((i+1)*x for i,x in enumerate(out))


