  public int chainInspectionBossReceipt(ListNode head) {
    ListNode a=head; List<Integer> out=new ArrayList<>();
    {for(ListNode node=a;node!=null;node=node.next)out.add(node.val);}
    int answer=0;for(int i=0;i<out.size();i++)answer+=(i+1)*out.get(i);return answer;
